export default async function(self, env, ctx) {
  // inspections for section 1 in May 2026
  let cursor=null; let all=[];
  do {
    const page = await env.TROM.read_records("inspections",
      ["id","section_id","date","schedule_id","schedule_asset_id","inspection_form_id","form_name"],
      [{field:"section_id", operator:"eq", value:1}],
      [{field:"date", direction:"asc"}], 500, cursor);
    all.push(...page.records);
    cursor=page.next_cursor;
  } while(cursor);
  console.log("total inspections section1: "+all.length);
  const may = all.filter(r=>r.date>="2026-05-01" && r.date<="2026-05-31");
  console.log("may2026 count: "+may.length);
  console.log(JSON.stringify(may.slice(0,50), null, 2));
}

